/**
 * A preview card shown on hover or focus (`design/components/hover-card.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/hover-card.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import * as zag from '@zag-js/hover-card'

import {
  MEMBER_PROVIDERS,
  Portal,
  Ref,
  SlotOutlet,
  SlotTemplate,
  Spread,
  TOOLTIP_DELAY_MS,
  TOOLTIP_SKIP_DELAY_MS,
  anchorProps,
  derived,
  devWarning,
  elementRef,
  mergeParts,
  normalizeProps,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  watchEffect,
} from '@polymorph/angular'
import { usePresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/overlays/hover-card.module.css'

export type HoverCardSide = NonNullable<HoverCardProps['side']>

export type HoverCardAlign = NonNullable<HoverCardProps['align']>

/** A preview card shown on hover or focus: the inputs it takes, by the React member's prop names. */
export interface HoverCardProps {
  align?: 'start' | 'center' | 'end'
  /**
   * Opens on mount, for galleries and tests; screens wait for the reader to hover.
   */
  defaultOpen?: boolean
  side?: 'bottom' | 'top' | 'right' | 'left'
}

/** A preview card shown on hover or focus. */
@Component({
  selector: 'pm-hover-card',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Portal, Ref, SlotOutlet, SlotTemplate, Spread],
  // prettier-ignore
  template: `<ng-template pmSlot="content" [pmSlotOf]="$"><ng-content select="[slot=content]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<!-- trigger -->
<span
[pmSpread]="e1()"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></span>
<ng-template pmPortal>@if (e2()) {<div
[pmSpread]="e3()"
><!-- panel -->
<div
[pmSpread]="e4()"
[pmRef]="panel"
><ng-container [pmSlotOutlet]="'content'" [pmSlotOf]="$" /></div></div>}</ng-template>`,
})
export class HoverCard {
  readonly align = input<Exclude<HoverCardProps['align'], undefined>, HoverCardProps['align']>(
    'start',
    { transform: (value: HoverCardProps['align']) => (value === undefined ? 'start' : value) },
  )
  /**
   * Opens on mount, for galleries and tests; screens wait for the reader to hover.
   */
  readonly defaultOpen = input<HoverCardProps['defaultOpen']>(undefined)
  readonly side = input<Exclude<HoverCardProps['side'], undefined>, HoverCardProps['side']>(
    'bottom',
    { transform: (value: HoverCardProps['side']) => (value === undefined ? 'bottom' : value) },
  )
  protected readonly $ = useMember({
    events: [],
    props: {
      align: () => this.align(),
      defaultOpen: () => this.defaultOpen(),
      side: () => this.side(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly panel = elementRef<HTMLElement>()
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          defaultOpen: this.$p.defaultOpen,
          openDelay: TOOLTIP_DELAY_MS,
          closeDelay: TOOLTIP_SKIP_DELAY_MS,
          positioning: {
            placement:
              this.$p.align === 'center' ? this.$p.side : `${this.$p.side}-${this.$p.align}`,
            offset: { mainAxis: 4 },
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  protected readonly present = setup(() =>
    usePresence(
      () => this.api.value.open,
      () => this.panel.value,
    ),
  )

  constructor() {
    watchEffect(
      () => this.api.value.open,
      () => this.effect1(),
      true,
    )
  }

  protected e1() {
    return mergeParts(anchorProps(this.api.value.getTriggerProps()), { class: styles.anchor })
  }

  protected e2() {
    return this.present.value()
  }

  protected e3() {
    if (!this.present.value()) return undefined as never
    return mergeParts(this.api.value.getPositionerProps())
  }

  protected e4() {
    if (!this.present.value()) return undefined as never
    return mergeParts(this.api.value.getContentProps(), {
      class: styles.panel,
      hidden: undefined,
      'data-member': 'hover-card',
    })
  }

  private effect1(): void {
    devWarning(
      this.api.value.open &&
        this.panel.value?.querySelector(
          'a[href], button, input, select, textarea, [tabindex]:not([tabindex="-1"])',
        ) != null,
      'HoverCard: the preview contains interactive content, which keyboard and touch readers can never reach. A card the reader must operate is a Popover.',
    )
  }
}
